def median_trapezium(a, b, c, d):
  lengths = sorted([a, b, c, d])
  n = len(lengths)
  if n % 2 == 0:
    median = (lengths[n//2 - 1] + lengths[n//2]) / 2
  else:
    median = lengths[n//2]
  return median

